TenantAppManagement = {
    init: async function(app, container, tenant) {
        container = container || $(".component[name=TenantAppManagement]");
        api.addToMetaCache([{ Name: "ContentManagement", Types: [[meta[ContentManagement/App]]] }]);
        var tenantId = tenant.Id.replaceAll("'", "''");
        var ds = await model.getDatasource({ endpoint: "ContentManagement/App", odataAppend: "?$filter=TenantId eq '" + tenantId + "'&$expand=Cultures" });
        var grid = new GridWidget(container, ds);
        grid.groupable = false;
        grid.filterable = true;
        grid.toolbar = [{ template: "<button class='btn btn-sm btn-primary' name='newApp'><span class='k-icon k-i-plus'></span>[resource_displayname[newapp]]</button>" }];
        grid.columns = [
            { field: "Name", title: "[resource_shortdisplayname[name]]" },
            { field: "Domain", title: "[resource_shortdisplayname[domain]]" },
            { title: "[resource_displayname[visit]]", width: 96, editable: false, template: function (data) { return "<a class='btn btn-sm btn-outline-primary' href='https://" + kendo.htmlEncode(data.Domain || "") + "/' target='_blank' rel='noopener'><span class='k-icon k-i-share'></span>[resource_displayname[visit]]</a>"; } }
        ];
        grid.detailTemplate = "<div name='tenantAppDetails'></div>";
        grid.detailExpand = function(e) {
            var selectedApp = grid.dataItem(e.masterRow);
            var host = $("[name=tenantAppDetails]", e.detailRow);
            if (host.data("app-initialised")) return;
            host.data("app-initialised", true);
            loadComponent(host, "AppManagement", async function() {
                var component = $(".component[name=AppManagement]", host);
                await AppManagement.init(selectedApp, component);
            });
        };
        await grid.init();
        $("button[name=newApp]", container).on("click", () => TenantAppManagement.openNewAppDialog(container, tenant, grid));
    },

    openNewAppDialog: async function(container, tenant, grid) {
        var dialog = new Dialog({ title: "[resource_displayname[newapp]]", width: 620, height: "auto" });
        dialog.template = $("template[name=newAppDialog]", container).html();
        dialog.events.create = async function() {
            var app = {
                Name: $("input[name=name]", dialog.element).val(),
                Domain: $("input[name=domain]", dialog.element).val(),
                TenantId: tenant.Id,
                DefaultCultureId: $("input[name=defaultCulture]", dialog.element).val(),
                DefaultTheme: $("input[name=defaultTheme]", dialog.element).val(),
                ConfigJson: "{}"
            };
            var selectedPaths = $("select[name=initialPackages]", dialog.element).val() || [];

            try {
                var createdApp = await api.add("ContentManagement/App", app);
                createdApp = createdApp.value || createdApp;

                for (var path of selectedPaths) {
                    var packageResponse = await fetch("/Assets/" + path);
                    if (!packageResponse.ok) throw new Error("Package could not be loaded: " + path);
                    var package = await packageResponse.json();
                    await api.post("Packaging/Package/Import?appId=" + createdApp.Id, package);
                }

                notification.success("[resource_displayname[appcreated]]");
                dialog.events.close();
                grid.refresh();
            } catch (exception) {
                await error(exception);
            }
        };
        dialog.init(async function() {
            var response = await fetch("/Assets/manifest.json");
            if (!response.ok) throw new Error("Package manifest could not be loaded.");
            var manifest = await response.json();
            var packages = manifest.Packages.filter(package => package.Source === "App" && !package.FirstTimeSetup);
            var selector = $("select[name=initialPackages]", dialog.element);
            packages.forEach(package => selector.append($("<option>").val(package.Path).text(package.Category)));
        });
    }
};
